<?php
declare(strict_types=1);
date_default_timezone_set('America/New_York');

$root = dirname(__DIR__);
$pageTarget = $root.'/admin_paid_payouts.php';
$helperTarget = $root.'/admin_paid_payouts_helper.php';
$backupRoot = $root.'/_installer_backups';
$stateFile = __DIR__.'/.install_admin_paid_payouts_balance_shortcut_v011_state.json';

$PAGE_B64 = '';
$HELPER_B64 = '';
$PAGE_SHA = '16824a38ea460d77b701ae89da1425932bf77c25b8b863437b3ea3cf04e61380';
$HELPER_SHA = '4086f5ea8054803363df43095d3322c202e8db33afaf14a439e8f78607795250';

function v11_h($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function v11_lint(string $path): array {
    $out = trim((string)@shell_exec('php -l '.escapeshellarg($path).' 2>&1'));
    return [strpos($out, 'No syntax errors detected') !== false, $out];
}
function v11_atomic(string $path, string $content): void {
    $tmp = $path.'.tmp_'.getmypid().'_'.bin2hex(random_bytes(3));
    if (@file_put_contents($tmp,$content,LOCK_EX) === false) throw new RuntimeException('Could not write '.basename($path));
    @chmod($tmp,0644);
    if (!@rename($tmp,$path)) { @unlink($tmp); throw new RuntimeException('Could not install '.basename($path)); }
    @chmod($path,0644);
}
function v11_load(string $path): array {
    if (!is_file($path)) return [];
    $d = json_decode((string)@file_get_contents($path),true);
    return is_array($d)?$d:[];
}
function v11_save(string $path,array $state): void {
    @file_put_contents($path,json_encode($state,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));
}

$page = base64_decode($PAGE_B64,true);
$helper = base64_decode($HELPER_B64,true);

$checks = [
    ['Installer running from /public_html/_installers', realpath(__DIR__)===realpath($root.'/_installers'), __DIR__],
    ['Current admin page exists', is_file($pageTarget), $pageTarget],
    ['Current helper exists', is_file($helperTarget), $helperTarget],
    ['Embedded v011 page decoded', is_string($page), is_string($page)?strlen($page).' bytes':'decode failed'],
    ['Embedded v010 helper decoded', is_string($helper), is_string($helper)?strlen($helper).' bytes':'decode failed'],
];

foreach ([['page',$page],['helper',$helper]] as $pair) {
    $tmp=tempnam(sys_get_temp_dir(),'mrl_v11_');
    @file_put_contents($tmp,$pair[1]);
    list($ok,$detail)=v11_lint($tmp);
    @unlink($tmp);
    $checks[]=['Candidate '.$pair[0].' php -l',$ok,$detail];
}

$preOk=true;
foreach($checks as $c) if(!$c[1]) $preOk=false;

$message='';
$state=v11_load($stateFile);

if ((string)($_POST['action']??'')==='apply' && $preOk) {
    try {
        if(!is_dir($backupRoot) && !@mkdir($backupRoot,0755,true) && !is_dir($backupRoot)) throw new RuntimeException('Could not create backup root.');
        $backupDir=$backupRoot.'/admin_paid_payouts_balance_shortcut_v011_'.date('Ymd_His');
        if(!@mkdir($backupDir,0755,true) && !is_dir($backupDir)) throw new RuntimeException('Could not create backup folder.');
        if(!@copy($pageTarget,$backupDir.'/admin_paid_payouts.php')) throw new RuntimeException('Could not back up admin page.');
        if(!@copy($helperTarget,$backupDir.'/admin_paid_payouts_helper.php')) throw new RuntimeException('Could not back up helper.');

        v11_atomic($helperTarget,$helper);
        v11_atomic($pageTarget,$page);

        foreach ([[$pageTarget,$PAGE_SHA],[$helperTarget,$HELPER_SHA]] as $item) {
            list($ok,$detail)=v11_lint($item[0]);
            if(!$ok) throw new RuntimeException(basename($item[0]).' failed php -l: '.$detail);
            if(hash_file('sha256',$item[0])!==$item[1]) throw new RuntimeException(basename($item[0]).' SHA mismatch.');
        }

        $state=['applied'=>true,'applied_at'=>date('c'),'backup_dir'=>$backupDir];
        v11_save($stateFile,$state);
        $message='PASS — v011 installed.';
    } catch(Throwable $e) {
        $message='FAIL — '.$e->getMessage();
    }
}

$state=v11_load($stateFile);
$post=[];
if(!empty($state['applied'])) {
    foreach ([[$pageTarget,$PAGE_SHA,'admin_paid_payouts.php'],[$helperTarget,$HELPER_SHA,'admin_paid_payouts_helper.php']] as $item) {
        $exists=is_file($item[0]);
        $post[]=[$item[2].' exists',$exists,$item[0]];
        if($exists) {
            list($ok,$detail)=v11_lint($item[0]);
            $post[]=[$item[2].' php -l',$ok,$detail];
            $post[]=[$item[2].' SHA matches',hash_file('sha256',$item[0])===$item[1],hash_file('sha256',$item[0])];
        }
    }
}
?>
