<p>Fixes the false same-team unsaved warning and adds the clickable Balance shortcut.</p>
<p><strong>No database schema or calculation changes.</strong></p></div>
<?php if($message!==''): ?><div class="card"><?php echo v11_h($message); ?></div><?php endif; ?>
<div class="card"><h2>PRECHECK</h2><table><tr><th>Status</th><th>Check</th><th>Detail</th></tr>
<?php foreach($checks as $c): ?><tr><td class="<?php echo $c[1]?'pass':'fail'; ?>"><?php echo $c[1]?'PASS':'FAIL'; ?></td><td><?php echo v11_h($c[0]); ?></td><td><?php echo v11_h($c[2]); ?></td></tr><?php endforeach; ?>
</table>
<?php if(empty($state['applied'])): ?><form method="post" style="margin-top:14px"><button class="btn" name="action" value="apply" <?php echo $preOk?'':'disabled'; ?>>Apply v011</button></form><?php endif; ?>
</div>
<?php if(!empty($state['applied'])): ?><div class="card"><h2>POSTCHECK</h2><table><tr><th>Status</th><th>Check</th><th>Detail</th></tr>
<?php foreach($post as $c): ?><tr><td class="<?php echo $c[1]?'pass':'fail'; ?>"><?php echo $c[1]?'PASS':'FAIL'; ?></td><td><?php echo v11_h($c[0]); ?></td><td><?php echo v11_h($c[2]); ?></td></tr><?php endforeach; ?>
</table><p style="margin-top:14px"><a class="btn" target="_blank" href="/admin_paid_payouts.php?year=2026">Open 2026 Paid/Payouts</a></p></div><?php endif; ?>
</div></body></html>
